#include <stdio.h>
#include <stdlib.h>

int main() {
    long long k;
    scanf("%lld", &k);

    // BFS to find lunlun numbers in order
    long long *queue = (long long*)malloc(sizeof(long long) * 10000000);
    int head = 0, tail = 0;

    // Initialize with 1-9
    for (int i = 1; i <= 9; i++) {
        queue[tail++] = i;
    }

    long long ans = 0;
    long long count = 0;

    while (head < tail) {
        long long num = queue[head++];
        count++;
        if (count == k) {
            ans = num;
            break;
        }

        int last_digit = num % 10;
        if (last_digit > 0) {
            queue[tail++] = num * 10 + (last_digit - 1);
        }
        queue[tail++] = num * 10 + last_digit;
        if (last_digit < 9) {
            queue[tail++] = num * 10 + (last_digit + 1);
        }
    }

    printf("%lld\n", ans);
    free(queue);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int K;
    scanf("%d", &K);

    // We will use a queue to generate lunlun numbers in increasing order.
    // Since K can be up to 10^5, we can use a simple array-based queue.
    long long queue[100005];
    int front = 0, rear = 0;

    // Initial lunlun numbers: 1 to 9
    for (int i = 1; i <= 9; i++) {
        queue[rear++] = i;
    }

    long long current;
    for (int i = 0; i < K; i++) {
        current = queue[front++];
        long long last_digit = current % 10;

        // Generate next numbers by appending digit d where |d - last_digit| <= 1
        if (last_digit > 0) {
            queue[rear++] = current * 10 + (last_digit - 1);
        }
        queue[rear++] = current * 10 + last_digit;
        if (last_digit < 9) {
            queue[rear++] = current * 10 + (last_digit + 1);
        }
    }

    printf("%lld\n", current);
    return 0;
}

