    /* BFS over lunlun numbers in increasing order */
    ull *q = (ull *)malloc(sizeof(ull) * 2000000);
    long long head = 0, tail = 0;

    for (int i = 1; i <= 9; i++) q[tail++] = (ull)i;

    ull ans = 0;
    for (long long cnt = 0; cnt < K; cnt++) {
        ull x = q[head++];
        ans = x;

        int d = (int)(x % 10);
        if (d > 0) q[tail++] = x * 10 + (d - 1);
        q[tail++] = x * 10 + d;
        if (d < 9) q[tail++] = x * 10 + (d + 1);
    }

    printf("%llu\n", ans);
    free(q);
    return 0;
}

